import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.DdtnLau3.js";const m=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function i(s,e,d,l,p,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p><strong>Core</strong> manages Works, Agents, Services and data on a Linux Docker host. <strong>CLI</strong> provides terminal user commands. The first trial uses one Linux computer and needs a supported model provider and API key.</p><ol><li><a href="/piwork/guide/quick-start.html">Quick Start</a>: Docker run by default, terminal login, Work creation and the first reply; native CLI is a folded alternative.</li><li><a href="/piwork/guide/installation.html">Installation and Deployment</a>: prerequisites, optional Core Compose Demo, troubleshooting and recovery.</li><li><a href="/piwork/guide/first-work.html">Your First Work</a>: a terminal file task, followed by stop, export, import and continuation.</li></ol><p>Already have a configured Core? Use the CLI entry in Quick Start directly.</p><p>Building an application? <a href="/piwork/guide/web-development.html">Web Development</a> covers the default base, automatic adoption, sqlite3, persistence and upgrades.</p><p>For model setup, see <a href="/piwork/guide/ai-models.html">AI Models</a>: one-form connections, message Test, Runtime defaults and Work/Thinking upgrade boundaries.</p><h2 id="current-scope" tabindex="-1">Current scope <a class="header-anchor" href="#current-scope" aria-label="Permalink to &quot;Current scope&quot;">​</a></h2><p>Published 0.0.2 Preview images target linux/amd64. Core uses Linux rootful Docker Engine 28+ and its local Unix socket. CLI runs on Linux or Windows Docker Desktop in Linux-container mode; Windows clients connect to Linux Core. Compose 2.24+ is only needed for the optional Core Demo or advanced setups.</p><p>WSL2 users need an available Linux Engine Unix socket; tested environments and boundaries are recorded in the <a href="https://github.com/pphboy/piwork/blob/main/docs/docker-quickstart-acceptance.md" target="_blank" rel="noreferrer">upstream terminal acceptance</a>. Desktop remains an independent entry; the terminal trial does not depend on it.</p><p>The <a href="/piwork/spec/">Spec overview</a> records source and image provenance. For an application example, see <a href="/piwork/demo/kanban.html">Kanban Work</a>.</p><p><a href="/piwork/guide/quick-start.html">Terminal Quick Start</a> uses independent Core/CLI images; Core also supports Core-only Compose, with combined usage in the single-host example; native builds and administrator operations have separate navigation.</p>',11)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
